const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point([-53.241, -29.645]); // Agudo, Brazil
    const aoi = point.buffer(5000); // 5 km radius

    const startDate = ee.Date('2023-11-05');
    const endDate = ee.Date('2023-11-21');

    // Function to mask clouds using the Sentinel-2 QA band.
    function maskS2clouds(image) {
        const qa = image.select('QA60');
        const cloudBitMask = 1 << 10;
        const cirrusBitMask = 1 << 11;
        const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
            .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
        return image.updateMask(mask).divide(10000);
    }

    // Function to calculate water area
    function calculateWaterArea(image) {
        // Calculate NDWI for water detection: (Green - NIR) / (Green + NIR)
        const ndwi = image.normalizedDifference(['B3', 'B8']).rename('ndwi');
        // A threshold of > 0.2 is often effective for separating water.
        const waterMask = ndwi.gt(0.2);
        // Calculate the area of water pixels
        const waterArea = waterMask.multiply(ee.Image.pixelArea()).reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: aoi,
            scale: 30,
            maxPixels: 1e9
        });
        return ee.Number(waterArea.get('ndwi'));
    }

    // 2. Data Acquisition & Check
    const s2Collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED');

    const imageStart = s2Collection
        .filterBounds(aoi)
        .filterDate(startDate.advance(-2, 'day'), startDate.advance(2, 'day'))
        .map(maskS2clouds)
        .sort('CLOUDY_PIXEL_PERCENTAGE')
        .first();

    const imageEnd = s2Collection
        .filterBounds(aoi)
        .filterDate(endDate.advance(-2, 'day'), endDate.advance(2, 'day'))
        .map(maskS2clouds)
        .sort('CLOUDY_PIXEL_PERCENTAGE')
        .first();

    // Ensure images exist
    const imageStartExists = ee.Algorithms.IsEqual(imageStart, null).not();
    const imageEndExists = ee.Algorithms.IsEqual(imageEnd, null).not();

    if (!imageStartExists.getInfo() || !imageEndExists.getInfo()) {
        console.log(`Image found for start period: ${imageStartExists.getInfo()}`);
        console.log(`Image found for end period: ${imageEndExists.getInfo()}`);
        console.log("Empty Collection: No valid S2 images found for one or both dates.");
        console.log("A"); // C1
        return;
    }

    // 3. Processing & Pixel Count Validation
    const startPixelCount = imageStart.select('B2').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: 30,
        maxPixels: 1e9
    }).get('B2');

    const endPixelCount = imageEnd.select('B2').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: 30,
        maxPixels: 1e9
    }).get('B2');

    if (startPixelCount.getInfo() === 0 || endPixelCount.getInfo() === 0) {
        console.log(`Valid pixels at start: ${startPixelCount.getInfo()}`);
        console.log(`Valid pixels at end: ${endPixelCount.getInfo()}`);
        console.log("No Valid Pixels: All pixels were masked due to clouds in one of the images.");
        console.log("C2");
        return;
    }

    // 4. Calculation
    const areaStart = calculateWaterArea(imageStart);
    const areaEnd = calculateWaterArea(imageEnd);

    const areaStartVal = areaStart.getInfo();
    const areaEndVal = areaEnd.getInfo();

    // 5. Validation & Final Answer
    if (areaStartVal === null || areaEndVal === null) {
        console.log(`Start Area: ${areaStartVal}`);
        console.log(`End Area: ${areaEndVal}`);
        console.log("Calculation Failure: Result was null.");
        console.log("C3");
        return;
    }

    const areaStartHa = areaStartVal / 10000;
    const areaEndHa = areaEndVal / 10000;

    console.log(`Water area on ~${startDate.format('YYYY-MM-dd').getInfo()}: ${areaStartHa.toFixed(2)} ha`);
    console.log(`Water area on ~${endDate.format('YYYY-MM-dd').getInfo()}: ${areaEndHa.toFixed(2)} ha`);
    console.log(`Pixel count (start): ${startPixelCount.getInfo()}, (end): ${endPixelCount.getInfo()}`);
    console.log(`Change in water area: ${(areaEndHa - areaStartHa).toFixed(2)} ha`);

    if (areaEndHa > areaStartHa) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
